#include "frame_png_export.h"
#include "layer_compositor.h"
#include <cwctype>
namespace moon {
std::vector<std::string> framePngExportFrameIds(const timeline::State& state,const FramePngExportOptions& options){
 if(state.frames.empty())throw std::invalid_argument("No frames to export");const auto& o=options.frames;
 for(const auto& section:state.loopSections)if(section.id==o.loopSectionId){auto r=timeline::loopRange(state,section);if(r.start>=0&&r.end>=0)return gifExportFrameIds(state,o);}
 const int start=o.loopSectionId.empty()?std::clamp(o.frameStart-1,0,int(state.frames.size())-1):0,end=o.loopSectionId.empty()?std::max(start,std::clamp(o.frameEnd-1,0,int(state.frames.size())-1)):int(state.frames.size())-1;std::vector<std::string> ids;for(int i=start;i<=end;++i)ids.push_back(state.frames[i].id);
 if(o.direction==GifDirection::Reverse||o.direction==GifDirection::ReversePingPong)std::reverse(ids.begin(),ids.end());if((o.direction==GifDirection::ForwardPingPong||o.direction==GifDirection::ReversePingPong)&&ids.size()>2){auto once=ids;for(int i=int(once.size())-2;i>0;--i)ids.push_back(once[i]);}return ids;
}
std::u32string framePngExportStem(std::u32string name,std::u32string fallback){auto dot=name.find_last_of(U'.');if(dot!=std::u32string::npos){auto extension=name.substr(dot+1);for(auto& c:extension)if(c>=U'A'&&c<=U'Z')c+=32;for(auto value:{U"moonsprite",U"aseprite",U"ase",U"png",U"jpg",U"jpeg",U"webp",U"bmp",U"svg",U"gif",U"ico",U"psd"})if(extension==value){name.resize(dot);break;}}for(auto& c:name)if(std::u32string(U"\\/:*?\"<>|").find(c)!=std::u32string::npos)c=U'_';auto white=[](char32_t c){return(c>=9&&c<=13)||c==32||c==0xa0||c==0x1680||(c>=0x2000&&c<=0x200a)||c==0x2028||c==0x2029||c==0x202f||c==0x205f||c==0x3000||c==0xfeff;};auto first=std::find_if_not(name.begin(),name.end(),white),last=std::find_if_not(name.rbegin(),name.rend(),white).base();return first>=last?fallback:std::u32string(first,last);}
std::optional<std::vector<std::filesystem::path>> planFrameSequencePaths(const std::filesystem::path& directory,std::u32string stem,std::size_t count,const ExportConflictResolver& resolve,FrameSequenceFormat format){
 const std::u32string extension=format==FrameSequenceFormat::Svg?U".svg":format==FrameSequenceFormat::Ico?U".ico":format==FrameSequenceFormat::Bmp?U".bmp":U".png";stem=framePngExportStem(std::move(stem));const auto digits=std::max<std::size_t>(3,std::to_string(count).size());std::vector<std::filesystem::path> paths;ExportConflictChoice bulk=ExportConflictChoice::Cancel;
 for(std::size_t i=0;i<count;++i){auto n=std::to_string(i+1);n.insert(0,digits-n.size(),'0');auto name=stem+U"-"+std::u32string(n.begin(),n.end());auto path=directory/std::filesystem::path(name+extension);if(std::filesystem::exists(path)){std::filesystem::path suggested;for(int suffix=1;suffix<10000;++suffix){auto s=std::to_string(suffix);auto candidate=directory/std::filesystem::path(name+U" ("+std::u32string(s.begin(),s.end())+U")"+extension);if(!std::filesystem::exists(candidate)){suggested=candidate;break;}}if(suggested.empty())return {};auto choice=bulk==ExportConflictChoice::Cancel?(resolve?resolve(path,suggested):ExportConflictChoice::Cancel):bulk;if(choice==ExportConflictChoice::Cancel)return {};if(choice==ExportConflictChoice::OverwriteAll)bulk=ExportConflictChoice::Overwrite;if(choice==ExportConflictChoice::RenameAll)bulk=ExportConflictChoice::Rename;if(choice==ExportConflictChoice::Rename||choice==ExportConflictChoice::RenameAll)path=suggested;}paths.push_back(std::move(path));}return paths;
}
std::optional<std::vector<std::filesystem::path>> planFramePngPaths(const std::filesystem::path& directory,std::u32string stem,std::size_t count,const ExportConflictResolver& resolve,bool bmp){return planFrameSequencePaths(directory,std::move(stem),count,resolve,bmp?FrameSequenceFormat::Bmp:FrameSequenceFormat::Png);}
static StaticImageExport prepareFrameRaster(const Document& d,const std::string& frameId,const FramePngExportOptions& o){
 int x0=0,y0=0,w=d.width(),h=d.height();auto pixels=compositeNormalRegion(d.timeline(),frameId,{0,0,w,h});
 if(d.timeline().state().layers.size()==1){const auto& layer=d.timeline().state().layers.front();if(layer.visible&&layer.opacity==1){auto slot=d.timeline().findCel(layer.id,frameId);auto resolved=d.timeline().resolveSurface(slot->id);if(resolved.surface){const auto& source=*resolved.surface;for(int y=0;y<h;++y)for(int x=0;x<w;++x){const int sx=x-source.offsetX,sy=y-source.offsetY;if(sx>=0&&sy>=0&&sx<source.width&&sy<source.height)pixels[std::size_t(y)*w+x]=source.pixels[std::size_t(sy)*source.width+sx];}}}}
 if(o.frames.trim){int left=w,top=h,right=-1,bottom=-1;for(int y=0;y<h;++y)for(int x=0;x<w;++x)if(pixels[std::size_t(y)*w+x]>>24){left=std::min(left,x);top=std::min(top,y);right=std::max(right,x);bottom=std::max(bottom,y);}if(right>=0){x0=left;y0=top;w=right-left+1;h=bottom-top+1;}}
 const int percent=std::clamp(o.frames.scalePercent,1,6400),outW=std::max(1,int(std::floor(w*percent/100.0+.5))),outH=std::max(1,int(std::floor(h*percent/100.0+.5)));if(std::uint64_t(outW)*outH>64*1024*1024)throw std::runtime_error("PNG exceeds native export memory budget");std::vector<Pixel> scaled(std::size_t(outW)*outH);for(int y=0;y<outH;++y)for(int x=0;x<outW;++x)scaled[std::size_t(y)*outW+x]=pixels[std::size_t(y0+std::uint64_t(y)*h/outH)*d.width()+x0+std::uint64_t(x)*w/outW];StaticImageExport out;out.width=outW;out.height=outH;out.pixels=std::move(scaled);return out;
}
StaticImageExport encodeFramePng(const Document& d,const std::string& id,const FramePngExportOptions& o){auto r=prepareFrameRaster(d,id,o);return encodeImagePng(r.width,r.height,std::move(r.pixels),o.automatic);}
BmpImageExport encodeFrameBmp(const Document& d,const std::string& id,const FramePngExportOptions& o){auto r=prepareFrameRaster(d,id,o);return {r.width,r.height,encodeImageBmp(r.width,r.height,r.pixels)};}
SvgImageExport encodeFrameSvg(const Document& d,const std::string& id,const FramePngExportOptions& o){auto r=prepareFrameRaster(d,id,o);return {r.width,r.height,encodeImageSvg(r.width,r.height,r.pixels)};}
IcoImageExport encodeFrameIco(const Document& d,const std::string& id,const FramePngExportOptions& o){auto r=prepareFrameRaster(d,id,o);return encodeImageIco(r.width,r.height,r.pixels);}
std::size_t writeFramePngSequence(const Document& d,const FramePngExportOptions& o,const std::vector<std::filesystem::path>& paths,const std::function<bool()>& cancelled,const std::function<void(std::size_t,std::size_t)>& progress){if(int(o.bmp)+int(o.ico)+int(o.svg)>1)throw std::invalid_argument("Ambiguous frame sequence format");auto ids=framePngExportFrameIds(d.timeline().state(),o);if(ids.size()!=paths.size())throw std::invalid_argument("Frame export destination mismatch");std::size_t written=0;for(std::size_t i=0;i<ids.size();++i){if(cancelled&&cancelled())return written;auto bytes=o.svg?encodeFrameSvg(d,ids[i],o).bytes:o.ico?encodeFrameIco(d,ids[i],o).bytes:o.bmp?encodeFrameBmp(d,ids[i],o).bytes:encodeFramePng(d,ids[i],o).png;if(cancelled&&cancelled())return written;writeExportBytesAtomic(paths[i],bytes);++written;if(progress)progress(written,ids.size());if(cancelled&&cancelled())return written;}return written;}
}
